          stop("Non-log-concave density detected at x =", x_cand)
        }
        samples[i] <- x_cand
        accepted <- TRUE

        # Update hull with new point if needed
        if (length(tangent_points) < 30) {
          tangent_points <- sort(c(tangent_points, x_cand))
