          derivatives <- sapply(tangent_points, numerical_derivative, log_density_fn = log_density_fn)
        }
      }
    }

    if (!accepted) {
      stop("Failed to generate sample", i, " after ", max_rejections, " rejections")
    }
  }

  return(samples)
}

